-- ==========================================================================
-- Item Upgrade Variants — auto-generated by tools/gen_item_variants.py
-- ==========================================================================
--
-- 80378 variants. entry = 1000000 + baseEntry*20 + step.
--
-- Both tables are required.  Without the item_dbc row the item_template
-- row is silently discarded at load (ObjectMgr.cpp:3487) and the item
-- simply does not exist; build_dbc.py also reads item_dbc to patch the
-- client's Item.dbc, which is what makes the bag icon resolve.
--
-- The 138-column item_template list is deliberately never written out:
-- rows are cloned with INSERT ... SELECT * and then patched by a JOIN
-- against the compact delta table, so this file survives schema changes.
--
-- ORDERING: this file clones base rows AT APPLY TIME, so it must sort
-- AFTER the gen_item_limit_categories.py output.  Applied first, variants
-- of unique-equipped items would clone ItemLimitCategory = 0 and stay
-- equippable alongside their own base item -- the exact dupe that file
-- exists to close.  Rename this file if the sequence numbers say otherwise.

DELETE FROM `item_template` WHERE `entry` >= 1000000;
DELETE FROM `item_dbc`      WHERE `ID`    >= 1000000;
DROP TABLE IF EXISTS `alonecraft_item_upgrade_variant`;
CREATE TABLE `alonecraft_item_upgrade_variant` (
  `entry` INT UNSIGNED NOT NULL PRIMARY KEY,
  `base_entry` INT UNSIGNED NOT NULL,
  `step` TINYINT UNSIGNED NOT NULL,
  `base_level` TINYINT UNSIGNED NOT NULL,
  `target_level` TINYINT UNSIGNED NOT NULL,
  `target_ilvl` SMALLINT UNSIGNED NOT NULL,
  `stat_mult` FLOAT NOT NULL,
  KEY `idx_base` (`base_entry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- Audit only. The runtime never reads this table; it exists so a human
-- can answer "why does this item have these stats", and so a future
-- retune can write a migration.

-- -- item_dbc -----

































































































































































-- -- audit table -----

































































































































































-- -- delta table -----
DROP TEMPORARY TABLE IF EXISTS `_woa_delta`;
CREATE TEMPORARY TABLE `_woa_delta` (
  `entry` INT UNSIGNED NOT NULL PRIMARY KEY,
  `base_entry` INT UNSIGNED NOT NULL,
  `step` TINYINT UNSIGNED NOT NULL,
  `req_level` TINYINT UNSIGNED NOT NULL,
  `item_level` SMALLINT UNSIGNED NOT NULL,
  `armor` INT UNSIGNED NOT NULL, `block` INT UNSIGNED NOT NULL,
  `dmin1` FLOAT NOT NULL, `dmax1` FLOAT NOT NULL,
  `dmin2` FLOAT NOT NULL, `dmax2` FLOAT NOT NULL,
  `sv1` INT NOT NULL, `sv2` INT NOT NULL, `sv3` INT NOT NULL, `sv4` INT NOT NULL, `sv5` INT NOT NULL, `sv6` INT NOT NULL, `sv7` INT NOT NULL, `sv8` INT NOT NULL, `sv9` INT NOT NULL, `sv10` INT NOT NULL,
  `r1` INT NOT NULL, `r2` INT NOT NULL, `r3` INT NOT NULL, `r4` INT NOT NULL, `r5` INT NOT NULL, `r6` INT NOT NULL,
  KEY `idx_step` (`step`)
) ENGINE=MEMORY;


































































































































































-- -- clone + patch, one pass per step -----
DROP TEMPORARY TABLE IF EXISTS `_woa_clone`;
CREATE TEMPORARY TABLE `_woa_clone` LIKE `item_template`;

DROP TEMPORARY TABLE IF EXISTS `_woa_rndgrp`;
CREATE TEMPORARY TABLE `_woa_rndgrp` (
  `cls` TINYINT UNSIGNED NOT NULL, `sub` TINYINT UNSIGNED NOT NULL,
  `inv` TINYINT UNSIGNED NOT NULL, `lvl` TINYINT UNSIGNED NOT NULL,
  `grp` INT UNSIGNED NOT NULL,
  PRIMARY KEY (`cls`, `sub`, `inv`, `lvl`)) ENGINE=MEMORY;



-- step 1  (+5 levels)
TRUNCATE `_woa_clone`;
UPDATE `_woa_clone` c JOIN `_woa_delta` d ON d.`base_entry` = c.`entry` AND d.`step` = 1 LEFT JOIN `_woa_rndgrp` g ON g.`cls` = c.`class` AND g.`sub` = c.`subclass` AND g.`inv` = c.`InventoryType` AND g.`lvl` = d.`req_level` SET
  c.`entry` = d.`entry`,
  c.`name` = CONCAT(CASE d.`req_level` WHEN 5 THEN IF(SUBSTRING_INDEX(c.`name`, ' ', 1) = 'Flickering', 'Guttering', 'Flickering') WHEN 10 THEN IF(SUBSTRING_INDEX(c.`name`, ' ', 1) = 'Dim', 'Faded', 'Dim') WHEN 15 THEN IF(SUBSTRING_INDEX(c.`name`, ' ', 1) = 'Glimmering', 'Twinkling', 'Glimmering') WHEN 20 THEN IF(SUBSTRING_INDEX(c.`name`, ' ', 1) = 'Radiant', 'Beaming', 'Radiant') WHEN 25 THEN IF(SUBSTRING_INDEX(c.`name`, ' ', 1) = 'Fractured', 'Riven', 'Fractured') WHEN 30 THEN IF(SUBSTRING_INDEX(c.`name`, ' ', 1) = 'Lucid', 'Limpid', 'Lucid') WHEN 35 THEN IF(SUBSTRING_INDEX(c.`name`, ' ', 1) = 'Gleaming', 'Burnished', 'Gleaming') WHEN 40 THEN IF(SUBSTRING_INDEX(c.`name`, ' ', 1) = 'Brilliant', 'Lustrous', 'Brilliant') WHEN 45 THEN IF(SUBSTRING_INDEX(c.`name`, ' ', 1) = 'Shifting', 'Wavering', 'Shifting') WHEN 50 THEN IF(SUBSTRING_INDEX(c.`name`, ' ', 1) = 'Resonant', 'Humming', 'Resonant') WHEN 55 THEN IF(SUBSTRING_INDEX(c.`name`, ' ', 1) = 'Coalesced', 'Fused', 'Coalesced') WHEN 60 THEN IF(SUBSTRING_INDEX(c.`name`, ' ', 1) = 'Refracted', 'Prismatic', 'Refracted') WHEN 65 THEN IF(SUBSTRING_INDEX(c.`name`, ' ', 1) = 'Woven', 'Threaded', 'Woven') WHEN 70 THEN IF(SUBSTRING_INDEX(c.`name`, ' ', 1) = 'Ascendant', 'Rising', 'Ascendant') WHEN 75 THEN IF(SUBSTRING_INDEX(c.`name`, ' ', 1) = 'Transcendent', 'Exalted', 'Transcendent') WHEN 80 THEN IF(SUBSTRING_INDEX(c.`name`, ' ', 1) = 'Eternal', 'Undying', 'Eternal') END, ' ', c.`name`),
  c.`RequiredLevel` = d.`req_level`,
  c.`RandomProperty` = IF(c.`RandomProperty` = 0, 0, COALESCE(g.`grp`, c.`RandomProperty`)),
  c.`ItemLevel` = d.`item_level`,
  -- Force BoP: without this an level-80 could upgrade cheap greens
  -- and sell them, creating a laundering and twink-gear market.
  c.`bonding` = 1,
  c.`armor` = d.`armor`, c.`block` = d.`block`,
  c.`dmg_min1` = d.`dmin1`, c.`dmg_max1` = d.`dmax1`,
  c.`dmg_min2` = d.`dmin2`, c.`dmg_max2` = d.`dmax2`,
  c.`stat_value1` = d.`sv1`, c.`stat_value2` = d.`sv2`, c.`stat_value3` = d.`sv3`, c.`stat_value4` = d.`sv4`, c.`stat_value5` = d.`sv5`, c.`stat_value6` = d.`sv6`, c.`stat_value7` = d.`sv7`, c.`stat_value8` = d.`sv8`, c.`stat_value9` = d.`sv9`, c.`stat_value10` = d.`sv10`,
  c.`holy_res` = d.`r1`, c.`fire_res` = d.`r2`, c.`nature_res` = d.`r3`, c.`frost_res` = d.`r4`, c.`shadow_res` = d.`r5`, c.`arcane_res` = d.`r6`;

